prompt --application/shared_components/navigation/lists/custom_nav_menu
begin
wwv_flow_imp_shared.create_list(
 p_id=>wwv_flow_imp.id(3392168170671941)
,p_name=>'Custom Nav Menu'
,p_list_type=>'SQL_QUERY'
,p_list_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
unistr('    LEVEL                 AS lvl,           -- Controla a identa\00E7\00E3o hier\00E1rquica nativa do APEX'),
unistr('    c.c002                AS label,         -- R\00F3tulo do menu (ENTRY_TEXT)'),
'    c.c003                AS target,        -- URL de destino (ENTRY_TARGET)',
'    ''YES''                 AS is_current,    -- Permite que o APEX gerencie o estado ativo automaticamente',
unistr('    c.c006                AS image          -- \00CDcone FontAwesome do menu (ENTRY_IMAGE)'),
'FROM ',
'    apex_collections c',
'WHERE ',
'    c.collection_name = ''RMAIS_ALLOWED_MENUS''',
unistr('-- Reconstr\00F3i dinamicamente os n\00EDveis de Menu Pai e Submenu com base nos IDs salvos'),
'START WITH ',
'    c.c005 IS NULL OR c.c005 = ''0''',
'CONNECT BY ',
'    PRIOR c.c004 = c.c005',
unistr('-- Mant\00E9m a ordena\00E7\00E3o exata estipulada no desenvolvimento da aplica\00E7\00E3o'),
'ORDER SIBLINGS BY ',
'    c.n001;',
''))
,p_list_status=>'PUBLIC'
);
end;
