 p_id=>wwv_flow_imp.id(2018387881882856)
,p_name=>'Links'
,p_parent_plug_id=>wwv_flow_imp.id(1891891441134087)
,p_template=>wwv_flow_imp.id(1813181150176082248)
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--noBorder:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-ContentRow--styleCompact'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH allowed_pages AS (',
'    SELECT DISTINCT',
'           smp.access_id,',
'           ua.page_id,',
'           ua.description page_name,',
'           sm.module_name,',
'           ''fa '' || sm.icon_class AS icon_class,',
'           smp.display_order,',
'           smp.is_default',
'      FROM rmais_users u',
'      JOIN rmais_users_user_groups uug',
'        ON uug.user_id = u.user_id',
'       AND uug.status = ''Y''',
'      JOIN rmais_sec_group_module_perm gmp',
'        ON gmp.group_id = uug.group_id',
'       AND gmp.status = ''Y''',
'       AND gmp.view_flag = ''Y''',
'      JOIN rmais_sec_modules sm',
'        ON sm.module_id = gmp.module_id',
'       AND sm.status = ''Y''',
'      JOIN rmais_sec_module_pages smp',
'        ON smp.module_id = sm.module_id',
'       AND smp.status = ''Y''',
'      JOIN rmais_users_access ua',
'        ON ua.access_id = smp.access_id',
'       AND ua.status = ''Y''',
'     WHERE UPPER(u.user_name) = UPPER(:APP_USER)',
'),',
'usage_stats AS (',
'    SELECT',
'        step_id page_id,',
'        COUNT(*) access_count,',
'        MAX(time_stamp) last_access',
'      FROM apex_activity_log',
'     WHERE flow_id = :APP_ID',
'       AND userid_lc = LOWER(:APP_USER)',
'     GROUP BY step_id',
'),',
'ranked_pages AS (',
'    SELECT',
'        ap.page_name AS title,',
'        ap.module_name AS description,',
'        NULL AS icon_html,',
'        NULL AS actions,',
'        NULL AS item_classes,',
'        NULL AS selection,',
'        NULL AS misc,',
'        ap.icon_class,',
'        ap.page_id,',
'        NVL(us.access_count, 0) AS access_count,',
'        us.last_access,',
'        ap.is_default,',
'        ap.display_order',
'    FROM allowed_pages ap',
'    LEFT JOIN usage_stats us',
'      ON us.page_id = ap.page_id',
'),',
'deduplicated_pages AS (',
'    SELECT rp.*,',
'           ROW_NUMBER() OVER (',
'               PARTITION BY rp.page_id',
'               ORDER BY',
'                   rp.last_access DESC NULLS LAST,',
'                   rp.access_count DESC,',
'                   CASE WHEN rp.is_default = ''Y'' THEN 0 ELSE 1 END,',
'                   rp.display_order,',
'                   rp.description',
'           ) AS rn',
'      FROM ranked_pages rp',
'     WHERE rp.page_id NOT IN (1, 9999)',
')',
'SELECT',
'    title,',
'    description,',
'    icon_html,',
'    actions,',
'    item_classes,',
'    selection,',
'    misc,',
'    icon_class,',
'    page_id',
'FROM deduplicated_pages',
'WHERE rn = 1',
'ORDER BY',
'    last_access DESC NULLS LAST,',
'    access_count DESC,',
'    CASE WHEN is_default = ''Y'' THEN 0 ELSE 1 END,',
'    display_order',
'FETCH FIRST 8 ROWS ONLY'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(1813203679335082257)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
