,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with',
'    TP_LINES as (',
'        select  B.EFD_HEADER_ID,',
'                max(B.SOURCE_DOCUMENT_TYPE) SOURCE_DOCUMENT_TYPE_LINE_MAX,',
'                max(B.item_code_efd) item_code_efd_MAX',
'        from    RMAIS_EFD_LINES B',
'        group by',
'                B.EFD_HEADER_ID',
'    )',
'SELECT   h.efd_header_id',
'        ,h.org_id',
'        ,h.organization_id',
'        ,h.location_id',
'        ,h.layout_version',
'        ,h.operation_type',
'        ,h.document_type',
'        ,h.ri_document_type_id',
'        ,h.source_document_type',
'        ,h.access_key_number',
'        ,h.usage_authorization',
'        ,h.event_code',
'        ,h.event_type',
'        ,h.event_date',
'        ,h.document_number document_number',
'        ,h.series',
unistr('        ,decode(h.model,''55'',''NFe'',''00'',''NFse'',''NF'',''NF'',''57'',''Cte'',''67'',''CTEos'',''06'',''Energia'',''21'',''Comunica\00E7\00E3o'',''22'',''Telecomunica\00E7\00E3o'',''28'',''G\00E1s'',''29'',''\00C1gua'',''97'',''Fatura de Aluguel'',''Modelo N\00E3o suportado'')  as model'),
'        ,trunc(h.issue_date) issue_date',
'        ,h.liable_freight_payment',
'        ,h.dar_number',
'        ,h.dar_total_amount',
'        ,h.dar_payment_date',
'        ,h.carrier_document_type',
'        ,h.carrier_address_state',
'        ,h.carrier_state_inscription',
'        ,h.carrier_vehicle_plate_number',
'        ,h.payment_term_id',
'        ,h.payment_base_date',
'        ,h.first_due_date',
'        ,to_char(h.total_amount,''FML999G999G999G999G990D00'') total_amount',
'        ,h.issuing_purpose',
'        ,h.issuing_type',
'        ,h.freight_modal',
'        ,h.gross_weight',
'        ,h.freight_unit_of_measure',
unistr('        --Comentado por Robson em 12/01/2023 ,decode(h.document_status,''N'',''A Receber'',''V'',''V\00E1lido'',''I'',''Inv\00E1lido'',''E'',''Erro'',''T'',''Enviado ERP'',''C'',''Cancelada'',''M'',''Manual'',''X'',''Cancelada Ap\00F3s Integra\00E7\00E3o'',''R'',''Rejeitado'',''RW'',''Rejeitado'',''W'',''Cancela')
||'da ERP'',''Status Desconhecido'')  document_status',
'        ,nvl(B.DESC_STATUS_DOCS,''Status Desconhecido'') document_status',
