,p_name=>unistr('Report Valida\00E7\00F5es')
,p_parent_plug_id=>wwv_flow_imp.id(1816526501085231329)
,p_template=>wwv_flow_imp.id(1813181150176082248)
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT --distinct l.line_number , nvl(ev.type,''Evento'') evento, message_text , trunc(ev.creation_date) "Data" ',
'     distinct case when ev.type||message_text like ''%Enviado para ERP%'' then null  else l.line_number end line_number',
'    , nvl(ev.type,''Evento'') evento',
'    , message_text ',
'    , trunc(ev.creation_date) "Data" ',
'FROM rmais_efd_lines l,',
'     RMAIS_EFD_LIN_VALID ev',
'WHERE (ev.efd_header_id = l.efd_header_id)',
'  AND (  L.efd_line_id  = ev.efd_line_id OR',
'         ev.efd_line_id IS NULL) ',
'  AND ev.efd_header_id = :P7_EFD_HEADER_ID',
unistr('  and message_text not like ''%tentativa de usar um LOB de uma tabela tempor\00E1ria, cujos dados j\00E1 foram expurgados%'''),
'order by 1 asc'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P7_EFD_HEADER_ID'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(1813210054849082260)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
