,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'update rmais_efd_lines',
'set item_code_efd     = :P8_ITEM_ERP,',
'    item_descr_efd    = :P8_ITEM_DESCR_ERP,',
'    CATALOG_CODE_NCM  = :P8_CATALOG_CODE_NCM_ERP,',
