'',
':P8_ITEM_OK := :P8_ITEM_ERP;',
':P8_ITEM_DESC_OK := :P8_ITEM_DESCR_ERP;',
':P8_TYPE2 := case when :P8_INVENTORY_ITEM_FLAG = ''Y'' then ''Goods'' else ''Services'' end;',
