,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    :P8_MSG_ALERT := '''';',
'    for C in ( ',
'        select  A.SEQ_ID,',
'                nvl(A.c019,A.n004) QUANT_LINE_ORIGINAL',
'        from    apex_collections A',
'        where   collection_name = ''RMAIS_PO_OK''',
'        and     A.SEQ_ID = :P8_ID_A',
'    ) loop',
'        if nls_num_char(:P8_VAL_A) > nls_num_char(C.QUANT_LINE_ORIGINAL) then',
unistr('            :P8_MSG_ALERT := ''A quantidade informada ultrapassa a quantidade dispon\00EDvel no pedido Rec: ''||:P8_VAL_A||'' Dsp: ''||C.QUANT_LINE_ORIGINAL;'),
'            :P8_VAL_A := C.QUANT_LINE_ORIGINAL;',
'        else',
'            apex_collection.update_member_attribute (',
'                    p_collection_name => ''RMAIS_PO_OK'',',
'                    p_seq => C.SEQ_ID,',
'                    p_attr_number    => 4,',
'                    p_number_value   => nls_num_char(:P8_VAL_A)',
'            );',
'        end if;',
'    end loop;',
'end;'))
,p_attribute_02=>'P8_VAL_A,P8_ID_A'
,p_attribute_03=>'P8_VAL_A,P8_MSG_ALERT'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
