wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(401293475063772828)
,p_event_id=>wwv_flow_imp.id(401293319488772826)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    with ',
'        TP_SPLIT as (',
'            select :P8_ARR_A SEQ_ID from dual',
'        ),',
'        TP_SPLIT_A as (',
'            select  regexp_substr(A.SEQ_ID, ''[^,]+'', 1, level) SEQ_ID',
'            from    TP_SPLIT A connect by level <= regexp_count(A.SEQ_ID, '','') + 1',
'        ),',
'        TP_RESULT as (',
'            select  sum(nvl(nls_num_char(A.c010) * nls_num_char(A.n004),0)) TOTAL_SEL',
'            from    apex_collections A,',
'                    TP_SPLIT_A B',
'            where   A.collection_name = ''RMAIS_PO_OK''',
'            and     A.SEQ_ID = B.SEQ_ID',
'        )',
'    select  A.TOTAL_SEL,',
'            case ',
'                when A.TOTAL_SEL > (nls_num_char(:P8_TOTAL_LINHA)) then 10 ',
'                when :P8_CTRL_A = 11 and A.TOTAL_SEL < (nls_num_char(:P8_TOTAL_LINHA)) then 13',
'                when :P8_CTRL_A = 11 then 12',
'            end',
'    into    :P8_SOMA_SPLIT,',
'            :P8_CTRL_A',
'    from    TP_RESULT A;',
'',
' end;',
' '))
,p_attribute_02=>'P8_ARR_A,P8_CTRL_A'
,p_attribute_03=>'P8_SOMA_SPLIT,P8_CTRL_A'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
