wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(1832326983910490397)
,p_computation_sequence=>10
,p_computation_item=>'P11_ACCESS_KEY_NUMBER'
,p_computation_type=>'FUNCTION_BODY'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'--return lpad(LPAD(nvl(:P11_ISSUER_DOCUMENT_NUMBER,''0''),15,''0'')||LPAD(nvl(:P11_RECEIVER_DOCUMENT_NUMBER,''0''),15,''0'')||:P11_DOCUMENT_NUMBER,44,''0'');',
'--ERA ESSE --return lpad(LPAD(nvl(:P11_ISSUER_DOCUMENT_NUMBER,''0''),15,''0'')||LPAD(nvl(:P11_RECEIVER_DOCUMENT_NUMBER,''0''),15,''0'')||to_char(to_date(:P11_ISSUE_DATE,''DD-MON-YYYY''),''YYYYMM'')||:P11_DOCUMENT_NUMBER,44,''0'');',
'return XXRMAIS_UTIL_V2_PKG.get_access_key_number(nvl(:P11_RECEIVER_DOCUMENT_NUMBER,''0''), nvl(:P11_ISSUER_DOCUMENT_NUMBER,''0''), to_date(:P11_ISSUE_DATE,''DD-MON-YYYY''), :P11_DOCUMENT_NUMBER);',
'--return lpad(LPAD(nvl(:P11_ISSUER_DOCUMENT_NUMBER,''0''),15,''0'')||LPAD(nvl(:P11_RECEIVER_DOCUMENT_NUMBER,''0''),15,''0'')||to_char(to_date(:P11_ISSUE_DATE,''DD-MON-YYYY''),''YYYYMM'')||LPAD(:P11_DOCUMENT_NUMBER,8,''0''),44,''0'');      ',
'--return lpad(LPAD(nvl(:P11_RECEIVER_DOCUMENT_NUMBER,''0''),15,''0'')||LPAD(nvl(:P11_ISSUER_DOCUMENT_NUMBER,''0''),15,''0'')||to_char(to_date(:P11_ISSUE_DATE,''DD-MON-YYYY''),''YYYYMM'')||LPAD(:P11_DOCUMENT_NUMBER,8,''0''),44,''0'');      ',
'--',
'exception when others then',
'raise_application_error(-20014,''Erro ao formar chave: ''||:P11_ISSUE_DATE);',
'end;'))
);
