unistr('        AND mensagem = ''Conclus\00E3o de Opera\00E7\00E3o Realizada'';'),
'    exception when others then  ',
'      l_aux := ''N'';',
'    end;',
'if :P39_DOCUMENT_STATUS = ''T'' and l_aux = ''N'' and  :P39_MODEL = ''55'' then  ',
'  return true;',
'else',
'  return false;',
'end if;',
'end;'))
,p_button_condition2=>'PLSQL'
,p_button_condition_type=>'FUNCTION_BODY'
);
