wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(709231534877996592)
,p_computation_sequence=>10
,p_computation_item=>'P69_ACCESS_KEY_NUMBER'
,p_computation_type=>'FUNCTION_BODY'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'--return lpad(LPAD(nvl(:P69_ISSUER_DOCUMENT_NUMBER,''0''),15,''0'')||LPAD(nvl(:P69_RECEIVER_DOCUMENT_NUMBER,''0''),15,''0'')||:P69_DOCUMENT_NUMBER,44,''0'');',
'--ERA ESSE --return lpad(LPAD(nvl(:P69_ISSUER_DOCUMENT_NUMBER,''0''),15,''0'')||LPAD(nvl(:P69_RECEIVER_DOCUMENT_NUMBER,''0''),15,''0'')||to_char(to_date(:P69_ISSUE_DATE,''DD-MON-YYYY''),''YYYYMM'')||:P69_DOCUMENT_NUMBER,44,''0'');',
'return XXRMAIS_UTIL_V2_PKG.get_access_key_number(nvl(:P69_RECEIVER_DOCUMENT_NUMBER,''0''), nvl(:P69_ISSUER_DOCUMENT_NUMBER,''0''), to_date(:P69_ISSUE_DATE,''DD-MON-YYYY''), :P69_DOCUMENT_NUMBER);',
'--return lpad(LPAD(nvl(:P69_ISSUER_DOCUMENT_NUMBER,''0''),15,''0'')||LPAD(nvl(:P69_RECEIVER_DOCUMENT_NUMBER,''0''),15,''0'')||to_char(to_date(:P69_ISSUE_DATE,''DD-MON-YYYY''),''YYYYMM'')||LPAD(:P69_DOCUMENT_NUMBER,8,''0''),44,''0'');      ',
'--return lpad(LPAD(nvl(:P69_RECEIVER_DOCUMENT_NUMBER,''0''),15,''0'')||LPAD(nvl(:P69_ISSUER_DOCUMENT_NUMBER,''0''),15,''0'')||to_char(to_date(:P69_ISSUE_DATE,''DD-MON-YYYY''),''YYYYMM'')||LPAD(:P69_DOCUMENT_NUMBER,8,''0''),44,''0'');      ',
'--',
'exception when others then',
'raise_application_error(-20014,''Erro ao formar chave: ''||:P69_ISSUE_DATE);',
'end;'))
);
