,p_affected_elements_type=>'ITEM'
,p_affected_elements=>'P69_VAL_LIQ'
,p_attribute_01=>'FUNCTION_BODY'
,p_attribute_06=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l NUMBER(15,2);',
'BEGIN',
'',
'  l := ( nvl(:P69_TOTAL_AMOUNT, 0) - (nvl(:P69_PIS_AMOUNT, 0) + nvl(:P69_COFINS_AMOUNT, 0) + nvl(:P69_INSS_TAX, 0) + nvl(:P69_INSS_AMOUNT, 0) + nvl(:P69_IR_AMOUNT, 0) + nvl(:P69_ISS_TAX, 0) + nvl(:P69_CSLL_AMOUNT, 0) + nvl(:P69_OTHER_EXPENSES_AMOUNT,'
||' 0) + nvl(:P69_DISCOUNT_AMOUNT, 0) ) );',
'',
'  if ( nvl(:P69_TOTAL_AMOUNT, 0) < 1 )',
'  THEN',
'    l := 0;',
'  END IF;',
'',
'  RETURN l;',
'',
'END;'))
,p_attribute_07=>'P69_TOTAL_AMOUNT,P69_PIS_AMOUNT,P69_COFINS_AMOUNT,P69_INSS_TAX,P69_INSS_AMOUNT,P69_IR_AMOUNT,P69_ISS_TAX,P69_CSLL_AMOUNT,P69_OTHER_EXPENSES_AMOUNT,P69_DISCOUNT_AMOUNT'
,p_attribute_08=>'Y'
,p_attribute_09=>'N'
,p_wait_for_result=>'Y'
