 p_id=>wwv_flow_imp.id(2302985504512173)
,p_plug_name=>'Manage WS Credentials'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(1813179302715082248)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    c.id,',
'    c.name                                      AS client_name,',
'    c.description,',
'    c.client_id,',
'    c.client_secret,',
'    SUBSTR(c.client_secret,1,6) || ''******'' AS client_secret_masked,',
'    c.auth_flow,',
'    CASE',
'        WHEN c.auth_flow = ''client_credentials''',
'        THEN ''u-success-text''',
'        ELSE ''u-warning-text''',
'    END                                         AS auth_flow_class,',
'    nvl(c.token_duration,''360'') as token_duration,',
'    c.support_email,',
'    cr.role_name,',
'    m.uri_prefix,',
'    c.created_by,',
'    c.created_on',
'',
'FROM user_ords_clients c',
'',
'LEFT JOIN user_ords_client_roles cr',
'       ON cr.client_name = c.name',
'',
'LEFT JOIN user_ords_roles r',
'       ON r.id = cr.role_id',
'',
'LEFT JOIN user_ords_privilege_roles pr',
'       ON pr.role_id = r.id              ',
'',
'LEFT JOIN user_ords_privileges p',
'       ON p.id = pr.privilege_id',
'',
'LEFT JOIN user_ords_privilege_modules pm',
'       ON pm.privilege_id = p.id',
'',
'LEFT JOIN user_ords_modules m',
'       ON m.id = pm.module_id',
'',
'ORDER BY c.created_on DESC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'Manage WS Credentials'
);
