wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2357221747890967)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GenerateClientCredentials'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_role_name_owa       owa.vc_arr;    ',
'    l_privilege_name      VARCHAR2(255);',
'    l_privilege_label     VARCHAR2(255);',
'    l_module_name         owa.vc_arr;',
'    l_module_uri          owa.vc_arr;',
'    l_client_name         VARCHAR2(255);',
'    l_client_description  VARCHAR2(4000);',
'    l_support_email       VARCHAR2(255);',
'    l_token_duration      NUMBER;',
'BEGIN',
'    SELECT',
'        c001,',
'        c002,',
'        c003,',
'        (select name from user_ords_modules where id = c004),',
'        c005,',
'        c006,',
'        c007,',
'        c008,',
'        c009',
'    INTO',
'        l_role_name_owa(1),',
'        l_privilege_name,',
'        l_privilege_label,',
'        l_module_name(1),',
'        l_module_uri(1),',
'        l_client_name,',
'        l_client_description,',
'        l_support_email,',
'        l_token_duration',
'    FROM apex_collections',
'    WHERE collection_name = ''RMAIS_ORDS_OAUTH_WIZARD'';',
'    -------------------------------------------------',
'    -- CREATE ROLE',
'    -------------------------------------------------',
'    ORDS.create_role(',
'        p_role_name => l_role_name_owa(1)',
'    );',
'    -------------------------------------------------',
'    -- CREATE PRIVILEGE',
'    -------------------------------------------------',
'    ORDS.define_privilege(',
'        p_privilege_name => l_privilege_name,',
'        p_roles          => l_role_name_owa,',
'        p_patterns       => l_module_uri,',
'        p_modules        => l_module_name,',
'        p_label          => l_privilege_label,',
'        p_description    => ''Provides access to ''||l_module_name(1)',
'    );',
'    -------------------------------------------------',
'    -- CREATE CLIENT',
'    -------------------------------------------------',
'    OAUTH.create_client(',
'        p_name              => l_client_name,',
'        p_grant_type        => ''client_credentials'',',
'        p_owner             => ''SCH_RMAIS_DEV'',',
'        p_description       => ''Client to consumer API ''||l_module_uri(1),',
'        p_support_email     => l_support_email,',
'        p_privilege_names   => l_privilege_name',
unistr('      --  p_token_duration    => l_token_duration -- Apresentando ERRO embora de acordo com a documenta\00E7\00E3o Oracle. Por default \00E9 3600 sec'),
'    );',
'',
'    -------------------------------------------------',
'    -- GRANT ROLE',
'    -------------------------------------------------',
'    OAUTH.grant_client_role(',
'        p_client_name => l_client_name,',
'        p_role_name   => l_role_name_owa(1)',
'    );',
'',
'    COMMIT;',
'    -------------------------------------------------',
'    -- CLEAR COLLECTION',
'    -------------------------------------------------',
'    APEX_COLLECTION.DELETE_COLLECTION(',
'        p_collection_name => ''RMAIS_ORDS_OAUTH_WIZARD''',
'    );',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        ROLLBACK;',
'        RAISE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>38743549789947023
);
