,p_autocomplete_on_off=>'OFF'
,p_step_template=>wwv_flow_imp.id(647330903153851670)
,p_page_template_options=>'#DEFAULT#:js-dialog-class-t-Drawer--pullOutEnd'
,p_protection_level=>'C'
,p_page_component_map=>'17'
,p_last_updated_by=>'TIAGO.CUCCO'
,p_last_upd_yyyymmddhh24miss=>'20260508185440'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(2403883440155080)
,p_plug_name=>'View Client Credentials'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(1813152766463082238)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    c.id,',
'    c.name                                      AS client_name,',
'    c.description,',
'    c.client_id,',
'    c.client_secret,',
'    SUBSTR(c.client_secret,1,6) || ''******'' AS client_secret_masked,',
'    c.auth_flow,',
'    CASE',
'        WHEN c.auth_flow = ''client_credentials''',
'        THEN ''u-success-text''',
'        ELSE ''u-warning-text''',
'    END                                         AS auth_flow_class,',
'    nvl(c.token_duration,''360'') as token_duration,',
'    c.support_email,',
'    cr.role_name,',
'    m.uri_prefix,',
'    c.created_by,',
'    c.created_on',
'',
'FROM user_ords_clients c',
'',
'LEFT JOIN user_ords_client_roles cr',
'       ON cr.client_name = c.name',
'',
'LEFT JOIN user_ords_roles r',
'       ON r.id = cr.role_id',
'',
'LEFT JOIN user_ords_privilege_roles pr',
'       ON pr.role_id = r.id              ',
'',
'LEFT JOIN user_ords_privileges p',
'       ON p.id = pr.privilege_id',
'',
'LEFT JOIN user_ords_privilege_modules pm',
'       ON pm.privilege_id = p.id',
'',
'LEFT JOIN user_ords_modules m',
'       ON m.id = pm.module_id',
'',
'WHERE c.id = :P9007_ID       ',
'',
'ORDER BY c.created_on DESC;'))
,p_is_editable=>false
,p_plug_source_type=>'NATIVE_FORM'
,p_plug_read_only_when_type=>'ALWAYS'
);
