wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2019735853882869)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Save Users Groups'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_selected_groups apex_t_varchar2;',
'BEGIN',
unistr('    -- 1. Converte a string do Shuttle (ex: ''10:20:30'') em uma cole\00E7\00E3o (array)'),
'    l_selected_groups := apex_string.split(:P10905_GROUPS, '':'');',
'',
'    -- 2. Remove os grupos',
'    DELETE FROM RMAIS_USERS_USER_GROUPS',
'    WHERE USER_ID = :P10905_USER_ID;',
'',
'    -- 3. Insere os grupos selecionados',
'    FOR i IN 1..l_selected_groups.count LOOP',
'            INSERT INTO RMAIS_USERS_USER_GROUPS(',
'                USER_ID, ',
'                GROUP_ID, ',
'                STATUS, ',
'                CREATION_DATE, ',
'                CREATED_BY, ',
'                UPDATED_DATE, ',
'                UPDATED_BY',
'            )',
'            VALUES (',
'                :P10905_USER_ID, ',
'                l_selected_groups(i), ',
'                ''Y'', ',
'                SYSDATE, ',
'                lower(:APP_USER), ',
'                SYSDATE, ',
'                lower(:APP_USER)',
'            );',
'    END LOOP;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>38406063895938925
);
